def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import sys
    import os

    if sys.platform == "win32" and cmd:
        script = cmd[0]
        if not os.path.isfile(script):
            shebang = None
            try:
                with open(script, 'r', encoding='utf-8') as f:
                    first_line = f.readline().strip()
                    if first_line.startswith('#!'):
                        shebang = first_line[2:].split()[0]
            except (OSError, UnicodeDecodeError):
                pass

            if shebang:
                if os.path.isfile(shebang):
                    return (shebang,) + cmd
                else:
                    shebang = os.path.join(os.path.dirname(sys.executable), shebang)
                    if os.path.isfile(shebang):
                        return (shebang,) + cmd

    return cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import subprocess

    if os.name != 'nt':
        return cmd

    def _get_shebang_first_line(filepath: str) -> str:
        try:
            with open(filepath, 'rb') as file:
                first_line = file.readline().strip()
                if first_line.startswith(b'#!'):
                    return first_line.decode('utf-8')
        except (FileNotFoundError, PermissionError):
            pass
        return ''

    if cmd and os.path.isfile(cmd[0]):
        shebang = _get_shebang_first_line(cmd[0])
        if shebang:
            shebang_parts = shebang.split()
            interpreter = shebang_parts[0][2:]  # Remove '#!'
            args = shebang_parts[1:] if len(shebang_parts) > 1 else []
            return (interpreter, *args, cmd[0], *cmd[1:])

    return cmd

