                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    merged = defaultdict(list)

    for key, value in nodes:
        key_value = key.value
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            # Deep merge the mapping nodes
            new_value = deep_merge_nodes(value.value)
        else:
            new_value = value

        found = False
        for i, (existing_key, existing_value) in enumerate(merged[key_value]):
            if isinstance(existing_value, ruamel.yaml.nodes.MappingNode) and isinstance(new_value, ruamel.yaml.nodes.MappingNode):
                merged[key_value][i] = (existing_key, ruamel.yaml.nodes.MappingNode(existing_value.tag, deep_merge_nodes(existing_value.value + new_value.value)))
                found = True
                break

        if not found:
            merged[key_value].append((key, new_value))

    result = []
    for key_value, values in merged.items():
        if len(values) > 1:
            # If there are multiple values, it means they were mapping nodes
            merged_value = []
            seen_keys = set()
            for key, value in values:
                if isinstance(value, ruamel.yaml.nodes.MappingNode):
                    for sub_key, sub_value in value.value:
                        if sub_key.value not in seen_keys:
                            seen_keys.add(sub_key.value)
                            merged_value.append((sub_key, sub_value))
            result.append((key, ruamel.yaml.nodes.MappingNode(values[0][1].tag, merged_value)))
        else:
            result.append(values[0])

    return result

