def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    # Assuming 'borgmatic.commands.borgmatic' is the module containing the command-line argument parsers
    import borgmatic.commands.borgmatic
    import argparse

    def extract_arguments(parser):
        argument_lines = []
        for action in parser._actions:
            if action.option_strings:
                argument_lines.append(' '.join(action.option_strings))
        return argument_lines

    def generate_completion_script():
        main_parser = borgmatic.commands.borgmatic.get_parser()
        main_commands = {}
        for action in main_parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for command, subparser in action.choices.items():
                    main_commands[command] = extract_arguments(subparser)

        completion_script = [
            '# bash completion for borgmatic',
            '_borgmatic()',
            '{',
            '    local cur prev opts',
            '    COMPREPLY=()',
            '    cur="${COMP_WORDS[COMP_CWORD]}"',
            '    prev="${COMP_WORDS[COMP_CWORD-1]}"',
            '    opts="' + ' '.join(main_commands.keys()) + '"',
            '',
            '    if [[ ${cur} == -* ]] ; then',
            '        COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )',
            '        return 0',
            '    fi',
        ]

        for command, options in main_commands.items():
            completion_script.extend([
                f'    if [[ ${prev} == "{command}" ]] ; then',
                f'        COMPREPLY=( $(compgen -W "{ " ".join(options) }" -- ${cur}) )',
                '        return 0',
                '    fi',
            ])

        completion_script.extend([
            '}',
            'complete -F _borgmatic borgmatic',
        ])

        return '\n'.join(completion_script)

    return generate_completion_script()

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('B'):
        size = size[:-1]
    if size.isdigit():
        return int(size)
    elif size.endswith('K'):
        return int(size[:-1]) * 1000
    elif size.endswith('M'):
        return int(size[:-1]) * 1000000
    elif size.endswith('G'):
        return int(size[:-1]) * 1000000000
    elif size.endswith('T'):
        return int(size[:-1]) * 1000000000000
    else:
        raise ValueError(f"Could not convert size {size}")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip().upper()
    if 'K' in size:
        return int(size.replace('K', '')) * 1000
    elif 'M' in size:
        return int(size.replace('M', '')) * 1000**2
    elif 'G' in size:
        return int(size.replace('G', '')) * 1000**3
    elif 'T' in size:
        return int(size.replace('T', '')) * 1000**4
    elif 'P' in size:
        return int(size.replace('P', '')) * 1000**5
    else:
        return int(size)

