def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = (1 if os.name == 'posix' else 0)

    if platform == 1:  # POSIX
        return re.split(r'\s+', s.strip())
    elif platform == 0:  # Windows/CMD
        return re.findall(r'(?:"([^"]*)")|(\S+)', s.strip())
    else:
        raise ValueError("Unsupported platform flag")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    if platform == 'this':
        import os
        if os.name == 'posix':
            platform = 1
        else:
            platform = 0

    if platform == 1:
        # POSIX
        return re.findall(r'"(?:[^\"](?:\\"|[^"])*")*[^"\s]*', s)
    elif platform == 0:
        # Windows/CMD
        return re.findall(r'(?:"((?:[^"]|\\")*)")|(^\s+|\s$|[\s^"'"]+)', s)
    else:
        raise ValueError("Unsupported platform value")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    if platform == 'this':
        import sys
        platform = 1 if sys.platform == 'win32' else 0

    if platform == 1:  # POSIX
        pattern = r"""(['"])(?:\\.|(?!\1)[^\\])*\1|\S+"""
    elif platform == 0:  # Windows/CMD
        pattern = r"""(["'])(?:\\.|(?!\1)[^\\])*\1|[^ ]+"""
    else:
        raise ValueError("Unsupported platform")

    return re.findall(pattern, s)

