def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        full_command = [command] + args
        if verbose:
            print('Running:', ' '.join(full_command))

        stderr = subprocess.DEVNULL if hide_stderr else None

        try:
            result = subprocess.run(full_command, cwd=cwd, env=env, check=True, stderr=stderr, stdout=subprocess.PIPE, text=True)
            if verbose:
                print('Output:', result.stdout)
            return result.stdout
        except subprocess.CalledProcessError as e:
            if verbose:
                print('Error:', e.stderr)
            raise Exception(f"Command '{' '.join(full_command)}' returned non-zero exit status {e.returncode}.") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    for command in commands:
        cmd = [command] + args
        if verbose:
            print("Running:", " ".join(cmd))
        with subprocess.Popen(cmd, cwd=cwd, env=env, stderr=subprocess.DEVNULL if hide_stderr else subprocess.STDOUT, stdout=subprocess.PIPE, text=True) as process:
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, cmd, output=stdout, stderr=stderr)
            if verbose:
                print(stdout)
    return stdout

