def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import logging.config
    import os

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            with open(config_filename) as config_file:
                config = {}
                if config_filename.endswith('.ini'):
                    config_parser = logging.config.ConfigParser()
                    config_parser.read_file(config_file)
                    config_parser.convert_to_dict(config)
                elif config_filename.endswith('.json'):
                    import json
                    config = json.load(config_file)
                elif config_filename.endswith('.yaml') or config_filename.endswith('.yml'):
                    import yaml
                    config = yaml.safe_load(config_file)
                else:
                    raise ValueError(f"Unsupported configuration file type: {config_filename}")

                if resolve_env:
                    config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

                if overrides:
                    config.update(overrides)

                config_dict[config_filename] = config

        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=config_filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(record)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename) as f:
                config.read_file(f)
            config_dict[filename] = config
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(record)

    if overrides:
        for section, settings in overrides.items():
            for key, value in settings.items():
                if section not in config_dict:
                    config_dict[section] = {}
                config_dict[section][key] = value

    if resolve_env:
        import os
        for config in config_dict.values():
            for section in config.sections():
                for key, value in config.items(section):
                    try:
                        config.set(section, key, os.path.expandvars(value))
                    except Exception as e:
                        record = logging.LogRecord(
                            name='config_loader',
                            level=logging.ERROR,
                            pathname=filename,
                            lineno=0,
                            msg=str(e),
                            args=(),
                            exc_info=True
                        )
                        log_records.append(record)

    return config_dict, log_records

