def load_config_file(file, resolve_env):
    import json
    config = json.load(file)
    if resolve_env:
        config = resolve_environment_variables(config)
    return config

def resolve_environment_variables(config):
    import os
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
            env_var = value[2:-1]
            config[key] = os.getenv(env_var, '')
        elif isinstance(value, dict):
            config[key] = resolve_environment_variables(value)
        elif isinstance(value, list):
            config[key] = [resolve_environment_variables(v) if isinstance(v, dict) else v for v in value]
    return config

